describe("doctests of sympy.stats", () => {
  it("P(X>3) # Probability X is greater than 3", () => {
    const X = new Sym('X');
    expect(sympyStr(P(Relational(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), rational(3), '>', { evaluate: false })))).toBe('1/2');
  });
  it("E(X+Y) # Expectation of the sum of two dice", () => {
    const [X, Y] = symbols('X Y');
    expect(sympyStr(expectation(add(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), new RandomSymbol(Y, new SingleFinitePSpace([Y, new DieDistribution([rational(6)])])))))).toBe('7');
  });
  it("variance(X+Y) # Variance of the sum of two dice", () => {
    const [X, Y] = symbols('X Y');
    expect(sympyStr(variance(add(new RandomSymbol(X, new SingleFinitePSpace([X, new DieDistribution([rational(6)])])), new RandomSymbol(Y, new SingleFinitePSpace([Y, new DieDistribution([rational(6)])])))))).toBe('35/6');
  });
  it("simplify(P(Z>1)) # Probability of Z being greater than 1", () => {
    expect(sympyStr(simplify(mul(rational(1, 4), pow(2, rational(1, 2)), pow(pi, rational(-1, 2)), add(mul(pow(2, rational(1, 2)), pow(pi, rational(1, 2))), mul(-1, pow(2, rational(1, 2)), pow(pi, rational(1, 2)), fn('erf', [mul(rational(1, 2), pow(2, rational(1, 2)))]))))))).toBe('1/2 - erf(sqrt(2)/2)/2');
  });
  it("E(Z)", () => {
    const x = new Sym('x');
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleContinuousPSpace([x, new ContinuousDistributionHandmade([Lambda([x], piecewise([exp(mul(-1, x)), And(Relational(x, rational(0), '>=', { evaluate: false }), Relational(x, oo, '<', { evaluate: false }))], [rational(0), true])), interval(rational(0), oo, false, true)])]))))).toBe('1');
  });
  it("P(Z > 5)", () => {
    const x = new Sym('x');
    expect(sympyStr(P(Relational(new RandomSymbol(x, new SingleContinuousPSpace([x, new ContinuousDistributionHandmade([Lambda([x], piecewise([exp(mul(-1, x)), And(Relational(x, rational(0), '>=', { evaluate: false }), Relational(x, oo, '<', { evaluate: false }))], [rational(0), true])), interval(rational(0), oo, false, true)])])), rational(5), '>', { evaluate: false })))).toBe('exp(-5)');
  });
  it("dist.pdf(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(new ContinuousDistributionHandmade([Lambda([x], exp(mul(-1, x))), interval(rational(0), oo, false, true)]).pdf(x))).toBe('exp(-x)');
  });
  it("E(D)", () => {
    const x = new Sym('x');
    const x_ = new Sym('x', { positive: true, integer: true });
    expect(sympyStr(expectation(new RandomSymbol(x, new SingleDiscretePSpace([x, new DiscreteDistributionHandmade([Lambda([x_], mul(rational(1, 2), pow(2, add(1, mul(-1, x_))))), Naturals])]))))).toBe('2');
  });
  it("P(D > 3)", () => {
    const x = new Sym('x');
    const x_ = new Sym('x', { positive: true, integer: true });
    expect(sympyStr(P(Relational(new RandomSymbol(x, new SingleDiscretePSpace([x, new DiscreteDistributionHandmade([Lambda([x_], mul(rational(1, 2), pow(2, add(1, mul(-1, x_))))), Naturals])])), rational(3), '>', { evaluate: false })))).toBe('1/8');
  });
  it("dist.pdf(x) (2)", () => {
    const x = new Sym('x', { positive: true, integer: true });
    expect(sympyStr(new DiscreteDistributionHandmade([Lambda([x], mul(rational(1, 2), pow(2, add(1, mul(-1, x))))), Naturals]).pdf(x))).toBe('2**(1 - x)/2');
  });
  it("E(X)", () => {
    const X = new Sym('X');
    expect(sympyStr(expectation(new RandomSymbol(X, new SingleFinitePSpace([X, new FiniteDistributionHandmade([Dict([[rational(1), rational(1, 3)], [rational(2), rational(1, 6)], [rational(3), rational(1, 4)], [rational(4), rational(1, 4)]])])]))))).toBe('29/12');
  });
  it("P(X > 3)", () => {
    const X = new Sym('X');
    expect(sympyStr(P(Relational(new RandomSymbol(X, new SingleFinitePSpace([X, new FiniteDistributionHandmade([Dict([[rational(1), rational(1, 3)], [rational(2), rational(1, 6)], [rational(3), rational(1, 4)], [rational(4), rational(1, 4)]])])])), rational(3), '>', { evaluate: false })))).toBe('1/4');
  });
  it.fails("dist.pmf(x)", () => {
    const x = new Sym('x', { positive: true, integer: true });
    expect(sympyStr(new FiniteDistributionHandmade([Dict([[rational(1), rational(1, 3)], [rational(2), rational(1, 6)], [rational(3), rational(1, 4)], [rational(4), rational(1, 4)]])]).pmf(x))).toBe('Lambda(x, Piecewise((1/3, Eq(x, 1)), (1/6, Eq(x, 2)), (1/4, Eq(x, 3) | Eq(x, 4)), (0, True)))');
  });
});

